// DecodeListOrganizationsRequest returns a decoder for requests sent to the
// admin listOrganizations endpoint.
func DecodeListOrganizationsRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*admin.ListOrganizationsPayload, error) {
	return func(r *http.Request) (*admin.ListOrganizationsPayload, error) {
		var payload *admin.ListOrganizationsPayload
		var (
			q                 *string
			accountType       *string
			accountTypes      []string
			trialStates       []string
			disabledStates    []string
			includeDisabled   *bool
			cursor            *string
			limit             *int
			sort              *string
			direction         *string
			page              *int
			adminSessionToken *string
			err               error
		)
		qp := r.URL.Query()
		qRaw := qp.Get("q")
		if qRaw != "" {
			q = &qRaw
		}
		accountTypeRaw := qp.Get("account_type")
		if accountTypeRaw != "" {
			accountType = &accountTypeRaw
		}
		accountTypes = qp["account_types"]
		trialStates = qp["trial_states"]
		disabledStates = qp["disabled_states"]
		{
			includeDisabledRaw := qp.Get("include_disabled")
			if includeDisabledRaw != "" {
				v, err2 := strconv.ParseBool(includeDisabledRaw)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("include_disabled", includeDisabledRaw, "boolean"))
				}
				includeDisabled = &v
			}
		}
		cursorRaw := qp.Get("cursor")
		if cursorRaw != "" {
			cursor = &cursorRaw
		}
		{
			limitRaw := qp.Get("limit")
			if limitRaw != "" {
				v, err2 := strconv.ParseInt(limitRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("limit", limitRaw, "integer"))
				}
				pv := int(v)
				limit = &pv
			}
		}
		sortRaw := qp.Get("sort")
		if sortRaw != "" {
			sort = &sortRaw
		}
		directionRaw := qp.Get("direction")
		if directionRaw != "" {
			direction = &directionRaw
		}
		{
			pageRaw := qp.Get("page")
			if pageRaw != "" {
				v, err2 := strconv.ParseInt(pageRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("page", pageRaw, "integer"))
				}
				pv := int(v)
				page = &pv
			}
		}
		adminSessionTokenRaw := r.Header.Get("Authorization")
		if adminSessionTokenRaw != "" {
			adminSessionToken = &adminSessionTokenRaw
		}
		if err != nil {
			return payload, err
		}
		payload = NewListOrganizationsPayload(q, accountType, accountTypes, trialStates, disabledStates, includeDisabled, cursor, limit, sort, direction, page, adminSessionToken)
		if payload.AdminSessionToken != nil {
			if strings.Contains(*payload.AdminSessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.AdminSessionToken, " ", 2)[1]
				payload.AdminSessionToken = &cred
			}
		}

		return payload, nil
	}
}

